@strawberry.type
class Query:
    @strawberry.field
    async def sprint_performance(self, info: Info, sprint_id: int) -> Optional[SprintPerformanceType]:
        user = info.context.get("current_user")
        if not user:
            raise HTTPException(status_code=401, detail="Authentication required")

        loader: DataLoader = info.context["sprint_metric_loader"]
        metric = await loader.load(sprint_id)
        if not metric:
            return None

        if metric.organization_id != user.organization_id:
            raise HTTPException(status_code=403, detail="Forbidden: access to sprint performance denied")

        return SprintPerformanceType(
            sprint_id=metric.sprint_id,
            completed_points=metric.completed_points,
            velocity_score=metric.velocity_score
        )
